 [UnityTest,Timeout(900000)] public IEnumerator FreshWholeV2PostLossRetryReceiptRestoredGetAndUnbindLifetime(){
  var file=Environment.GetEnvironmentVariable("LASTRAIL_FULL_V2_CONNECTION");if(string.IsNullOrEmpty(file))Assert.Ignore("Explicit disposable original GAME/SQL bridge required");var connection=JObject.Parse(File.ReadAllText(file));var token=new GameApiAccessToken((string)connection["token"]);var fresh=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BResultV2Transport-20261006/fresh-whole-v2-export.json"));var packet=(JObject)fresh["sourceBundle"];var bundle=BNativeNodeSourceSnapshot.Read(packet.ToString(),(string)packet["packetHash"],"a",(string)connection["runId"]);var binding=BRouteNativeTests.Binding(bundle.Boarding);var geometry=BOrdinaryGeometryTests.Geometry(binding);Assert.IsTrue(JToken.DeepEquals(fresh["binding"],binding.Capture()));Assert.IsTrue(JToken.DeepEquals(fresh["geometry"],geometry.Capture()));var motion=(JObject)fresh["motion"];var composition=new BRouteNativeComposition(bundle.Route,bundle.Boarding,binding,geometry,BTravelRuntimeConfiguration.LocalValidation(motion,BDirectAttackInput.Digest(motion)),10000);var saved=(JObject)fresh["controller"];
