   var arm=raw.SendAsync(new RunApiHttpRequest("GET","/__qa_drop_next",null,null),token);yield return Wait(arm);Assert.AreEqual(200,arm.GetAwaiter().GetResult().Response.StatusCode);var lost=c.SubmitOriginalResultReportAsync(original,request,client,token);yield return Wait(lost);var network=lost.Exception.GetBaseException() as BResultReportHttpException;Assert.NotNull(network);Assert.IsTrue(network.CanRetrySameRequest);var retry=c.SubmitOriginalResultReportAsync(original,request,client,token);yield return Wait(retry);var delivered=retry.GetAwaiter().GetResult();Assert.AreEqual(BLocalObservationDeliveryStatus.Forwarded,delivered.Status);var receipt=delivered.Receipt;var r=receipt.Capture();Assert.AreEqual(BResultConsistencyReceipt.V2Version,(string)r["version"]);Assert.IsFalse(receipt.ProgressAuthorized);Assert.AreEqual("ORIGINAL_DEPARTURE_FORMATION",(string)r["missingSources"][0]);Assert.AreEqual("resume-basic-361",(string)r["originalEventId"]);Assert.AreEqual("resume-step-362",(string)r["finalCommandId"]);Assert.AreEqual(1048,(long)r["originalJournal"]["waves"][1]["rawSequence"]);Assert.AreEqual(1063,(long)r["originalJournal"]["waves"][1]["pointSequence"]);Assert.IsFalse((bool)r["arrivalAccepted"]);Assert.IsFalse((bool)r["rewardsAuthorized"]);Assert.IsTrue(JToken.DeepEquals(saved,c.Capture()));
   var corruptionChecks=new JArray();foreach(string kind in new[]{"raw","point","terminal","final","eventRef","journalHash","revisionString","arrival","progress"}){var bad=receipt.Capture();switch(kind){case "raw":bad["originalJournal"]["waves"][1]["rawSequence"]=1063;break;case "point":bad["originalJournal"]["waves"][1]["pointSequence"]=1048;break;case "terminal":bad["originalEventId"]="resume-step-362";break;case "final":bad["finalCommandId"]="resume-basic-361";break;case "eventRef":bad["originalJournal"]["terminal"]["eventRef"]=receipt.EvidenceRef;break;case "journalHash":bad["originalJournal"]["journalHash"]="sha256:"+new string('0',64);break;case "revisionString":bad["commandRevision"]="507";break;case "arrival":bad["arrivalAccepted"]=true;break;case "progress":bad["progressAuthorized"]=true;break;}Assert.Throws<ArgumentException>(()=>BResultConsistencyReceipt.Read(bad.ToString(),request));corruptionChecks.Add(kind);}
   var replay=client.SubmitAsync(request,token);yield return Wait(replay);Assert.IsTrue(JToken.DeepEquals(r,replay.GetAwaiter().GetResult().Capture()));var duplicate=c.SubmitOriginalResultReportAsync(original,request,client,token);yield return Wait(duplicate);Assert.AreEqual(BLocalObservationDeliveryStatus.AlreadyForwarded,duplicate.GetAwaiter().GetResult().Status);
   using(var restarted=BRouteSessionController.Restore(saved,BDirectAttackInput.Digest(saved),composition.RestoreNative,"a",request.RunId)){var capture=restarted.CaptureOriginalRuntimeObservation();var persisted=request.Capture();var recoveredRequest=BResultReportRequest.Restore(persisted,BDirectAttackInput.Digest(persisted),capture);Assert.AreEqual(request.BodyJson,recoveredRequest.BodyJson);int callbacks=0;restarted.Bind(_=>callbacks++);var delay=raw.SendAsync(new RunApiHttpRequest("GET","/__qa_delay_next_get",null,null),token);yield return Wait(delay);Assert.AreEqual(200,delay.GetAwaiter().GetResult().Response.StatusCode);var canceled=restarted.RecoverOriginalResultReportAsync(capture,recoveredRequest,receipt.EvidenceRef,client,token);restarted.Unbind();yield return Wait(canceled);Assert.IsTrue(canceled.IsCanceled||canceled.IsFaulted);if(canceled.IsFaulted)Assert.IsInstanceOf<OperationCanceledException>(canceled.Exception.GetBaseException());Assert.AreEqual(0,callbacks);var get=restarted.RecoverOriginalResultReportAsync(capture,recoveredRequest,receipt.EvidenceRef,client,token);yield return Wait(get);var recovered=get.GetAwaiter().GetResult();Assert.AreEqual(BLocalObservationDeliveryStatus.Forwarded,recovered.Status);Assert.IsTrue(JToken.DeepEquals(r,recovered.Receipt.Capture()));Assert.IsTrue(JToken.DeepEquals(saved,restarted.Capture()));}
   var errors=new JArray();foreach(int status in new[]{401,409,413}){var body=request.Body();var auth=token;if(status==401)auth=new GameApiAccessToken("lst1.invalid-test-only");if(status==409)body["nodeSession"]["localRevision"]=99;if(status==413)body["oversizedTestPadding"]=new string('x',1600000);var wire=new RunApiHttpRequest("POST","/v1/runs/"+request.RunId+"/b-result-reports",body.ToString(Newtonsoft.Json.Formatting.None),new[]{new RunApiHttpHeader("Content-Type","application/json"),new RunApiHttpHeader("X-B-Result-Version",request.ReportVersion),new RunApiHttpHeader("Idempotency-Key",request.RequestId)});var send=raw.SendAsync(wire,auth);yield return Wait(send);var response=send.GetAwaiter().GetResult().Response;Assert.AreEqual(status,response.StatusCode);errors.Add(new JObject{["status"]=status,["code"]=RunApiErrorJsonAdapter.OptionalString(response.BodyJson,"errorCode")});}
   var unknown=client.RecoverAsync(request,"unknown",token);yield return Wait(unknown);Assert.AreEqual(404,((BResultReportHttpException)unknown.Exception.GetBaseException()).StatusCode);File.WriteAllText(Qa+"actual-http-full-v2.json",new JObject{["input"]="UNCHANGED_PRESERVED_FRESH_WHOLE_V2_EXPORT",["request"]=request.Capture(),["receipt"]=r,["responseLostAfterRealCommit"]=true,["sameBodyRetryAndReceiptReplay"]=true,["controllerAndRequestRestoredGet"]=true,["unboundRecoveryCanceledNoLateReceiptOrCallback"]=true,["sameRequestRecoveryAfterCancellation"]=true,["controllerUnchanged"]=true,["corruptReceiptCasesRejected"]=corruptionChecks,["errors"]=errors,["unknownRefStatus"]=404,["freshProducerRerun"]=false,["strictControllerRestoreReplayedOriginalCommands"]=true,["assembledV1PlusJournal"]=false,["newOperatingStart"]=false,["nativeFactoryAssignmentBound"]=false}.ToString());
